#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

bool isPalindrome(string text) {
    string cleaned = "";
    for (char c : text) {
        if (isalnum(c)) {
            cleaned += tolower(c);
        }
    }

    string reversed = cleaned;
    reverse(reversed.begin(), reversed.end());

    return cleaned == reversed;
}

int main() {
    string testStrings[] = {"radar", "hello", "level", "A man a plan a canal Panama"};

    for (int i = 0; i < 4; i++) {
        bool result = isPalindrome(testStrings[i]);
        cout << "'" << testStrings[i] << "' 是回文: " << (result ? "是" : "否") << endl;
    }

    return 0;
}
